$root='<WINDOWS_FIXTURE>';$ErrorActionPreference='Stop';foreach($e in @(Get-Content -Raw (Join-Path $root 'final-input-hashes.json')|ConvertFrom-Json)){if((Get-FileHash (Join-Path $root $e.path) -Algorithm SHA256).Hash -ne $e.sha256){throw 'final input transfer mismatch'};(Get-Item (Join-Path $root $e.path)).IsReadOnly=$true};foreach($name in @('runtime-common.ps1','finish-stopped.ps1')){$tokens=$null;$errors=$null;$null=[System.Management.Automation.Language.Parser]::ParseFile((Join-Path $root $name),[ref]$tokens,[ref]$errors);if($errors.Count -gt 0){throw ($errors|Out-String)}};& (Join-Path $root 'finish-stopped.ps1');$items=@(Get-ChildItem $root -File|Where-Object {$_.Extension -in @('.json','.ps1')}|Select-Object -ExpandProperty Name)+@('logs','runtime');& tar.exe -cf (Join-Path $root 'raw-evidence.tar') -C $root @items;if($LASTEXITCODE -ne 0){throw 'evidence archive failed'};[ordered]@{sha256=(Get-FileHash (Join-Path $root 'raw-evidence.tar') -Algorithm SHA256).Hash.ToLower();bytes=(Get-Item (Join-Path $root 'raw-evidence.tar')).Length}|ConvertTo-Json